CREATE SCHEMA IF NOT EXISTS resilience;
CREATE TABLE resilience.service_dependencies(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,service_key text NOT NULL,dependency_key text NOT NULL,criticality text NOT NULL CHECK(criticality IN('critical','important','optional')),timeout_ms integer NOT NULL CHECK(timeout_ms BETWEEN 50 AND 60000),retry_attempts integer NOT NULL CHECK(retry_attempts BETWEEN 0 AND 8),circuit_threshold integer NOT NULL CHECK(circuit_threshold BETWEEN 1 AND 100),fallback_mode text NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(tenant_id,service_key,dependency_key));
CREATE TABLE resilience.policies(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,service_key text NOT NULL,rto_seconds integer NOT NULL CHECK(rto_seconds>0),rpo_seconds integer NOT NULL CHECK(rpo_seconds>=0),minimum_healthy_replicas integer NOT NULL CHECK(minimum_healthy_replicas>0),maximum_replica_lag_seconds integer NOT NULL CHECK(maximum_replica_lag_seconds>=0),degradation_plan jsonb NOT NULL,version integer NOT NULL DEFAULT 1,published_at timestamptz,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(tenant_id,service_key,version));
CREATE TABLE resilience.chaos_experiments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,target_service text NOT NULL,fault_type text NOT NULL CHECK(fault_type IN('latency','error','cpu','memory','pod-kill','network-loss','dependency-loss')),environment text NOT NULL CHECK(environment IN('development','staging','production')),state text NOT NULL CHECK(state IN('draft','queued','running','passed','failed','aborted','rolled_back')),blast_radius_bps integer NOT NULL CHECK(blast_radius_bps BETWEEN 1 AND 5000),duration_seconds integer NOT NULL CHECK(duration_seconds BETWEEN 10 AND 1800),steady_state jsonb NOT NULL DEFAULT '{}'::jsonb,abort_conditions jsonb NOT NULL DEFAULT '{}'::jsonb,requested_by uuid NOT NULL,approved_by uuid,started_at timestamptz,finished_at timestamptz,created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE INDEX resilience_chaos_queue_idx ON resilience.chaos_experiments(tenant_id,state,created_at DESC);
CREATE TABLE resilience.recovery_drills(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,scenario text NOT NULL,state text NOT NULL CHECK(state IN('planned','running','passed','failed','aborted')),rto_seconds integer NOT NULL,rpo_seconds integer NOT NULL,recovered_in_seconds integer,data_loss_seconds integer,checksum_valid boolean,schema_valid boolean,sample_reads_passed boolean,requested_by uuid NOT NULL,approved_by uuid,started_at timestamptz,finished_at timestamptz,created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE INDEX resilience_recovery_drill_idx ON resilience.recovery_drills(tenant_id,state,created_at DESC);
CREATE TABLE resilience.failover_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,service_key text NOT NULL,from_node text NOT NULL,to_node text,action text NOT NULL CHECK(action IN('stay','promote','freeze_writes','rollback')),replica_lag_seconds integer NOT NULL DEFAULT 0,write_queue_depth integer NOT NULL DEFAULT 0,evidence jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE resilience.daily_metrics(tenant_id uuid NOT NULL,metric_date date NOT NULL,protected_services integer NOT NULL DEFAULT 0,open_circuits integer NOT NULL DEFAULT 0,active_experiments integer NOT NULL DEFAULT 0,rto_pass_bps integer NOT NULL DEFAULT 10000,rpo_pass_bps integer NOT NULL DEFAULT 10000,last_restore_seconds integer NOT NULL DEFAULT 0,PRIMARY KEY(tenant_id,metric_date));
CREATE OR REPLACE FUNCTION resilience.evidence_append_only()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RAISE EXCEPTION 'resilience evidence is append only';END$$;
CREATE TRIGGER resilience_failover_append_only BEFORE UPDATE OR DELETE ON resilience.failover_events FOR EACH ROW EXECUTE FUNCTION resilience.evidence_append_only();
ALTER TABLE resilience.service_dependencies ENABLE ROW LEVEL SECURITY;ALTER TABLE resilience.policies ENABLE ROW LEVEL SECURITY;ALTER TABLE resilience.chaos_experiments ENABLE ROW LEVEL SECURITY;ALTER TABLE resilience.recovery_drills ENABLE ROW LEVEL SECURITY;ALTER TABLE resilience.failover_events ENABLE ROW LEVEL SECURITY;ALTER TABLE resilience.daily_metrics ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation_dependencies ON resilience.service_dependencies USING(tenant_id=current_setting('app.current_tenant_id')::uuid)WITH CHECK(tenant_id=current_setting('app.current_tenant_id')::uuid);CREATE POLICY tenant_isolation_policies ON resilience.policies USING(tenant_id=current_setting('app.current_tenant_id')::uuid)WITH CHECK(tenant_id=current_setting('app.current_tenant_id')::uuid);CREATE POLICY tenant_isolation_experiments ON resilience.chaos_experiments USING(tenant_id=current_setting('app.current_tenant_id')::uuid)WITH CHECK(tenant_id=current_setting('app.current_tenant_id')::uuid);CREATE POLICY tenant_isolation_drills ON resilience.recovery_drills USING(tenant_id=current_setting('app.current_tenant_id')::uuid)WITH CHECK(tenant_id=current_setting('app.current_tenant_id')::uuid);CREATE POLICY tenant_isolation_failover ON resilience.failover_events USING(tenant_id=current_setting('app.current_tenant_id')::uuid)WITH CHECK(tenant_id=current_setting('app.current_tenant_id')::uuid);CREATE POLICY tenant_isolation_metrics ON resilience.daily_metrics USING(tenant_id=current_setting('app.current_tenant_id')::uuid)WITH CHECK(tenant_id=current_setting('app.current_tenant_id')::uuid);
